            $this->pdo->prepare("UPDATE job_tickets SET status='quoting',version=version+1 WHERE id=UNHEX(:id)")->execute(['id'=>$ticketId]);$this->pdo->prepare("UPDATE job_ticket_direct_invites SET status='quoted',responded_at=UTC_TIMESTAMP(6) WHERE ticket_id=UNHEX(:ticket) AND recipient_user_id=UNHEX(:user)")->execute(['ticket'=>$ticketId,'user'=>$bidderUserId]);
            $version=(int)$ticket['version']+1;$this->ticketInbox($ticket,$ticket['poster_user_id'],'job_ticket_quote_received','Job ticket quotation received',(string)$ticket['title'].' received a governed quotation.',['ticketId'=>$ticketId,'quotationId'=>$id]);(new AuditService($this->pdo))->append($ticket['organisation_id'],$bidderUserId,'job_ticket.quotation_submitted','job_ticket',$ticketId,['quotationId'=>$id,'bidderOrganisationId'=>$bidderOrganisationId,'bidderRole'=>$bidderRole,'snapshotSha256'=>$evidence['sha256']]);
            return['id'=>$id,'ticketId'=>$ticketId,'status'=>'submitted','amount'=>$quote['amount'],'currency'=>$quote['currency'],'snapshotSha256'=>$evidence['sha256'],'ticketVersion'=>$version];
        });
    }

    /** @return list<array<string,mixed>> */
    public function listQuotations(string$organisationId,string$userId,string$role,string$ticketId,bool$includeWithdrawn=false):array
    {
        $this->assertMember($organisationId,$userId,$role,['owner','admin','member','viewer']);$ticket=$this->ticketRow($ticketId,false);$posterAccess=$ticket['organisation_id']===$organisationId&&($ticket['poster_user_id']===$userId||in_array($role,['owner','admin'],true));$holderAccess=$ticket['holder_organisation_id']===$organisationId&&$ticket['holder_user_id']===$userId;if(!$posterAccess&&!$holderAccess)throw new JobTicketMarketplaceException('job_ticket_quotation_access_denied');$sql='SELECT LOWER(HEX(id)) id,LOWER(HEX(bidder_organisation_id)) bidder_organisation_id,LOWER(HEX(bidder_user_id)) bidder_user_id,bidder_role,amount,currency,scope,exclusions,qualifications,deliverables,timeline,conflict_declared,conflict_detail,snapshot_sha256,status,DATE_FORMAT(submitted_at,\'%Y-%m-%dT%H:%i:%s.%fZ\') submitted_at FROM job_ticket_quotations WHERE ticket_id=UNHEX(:ticket)'.($includeWithdrawn?'':" AND status<>'withdrawn'").' ORDER BY submitted_at,id';$statement=$this->pdo->prepare($sql);$statement->execute(['ticket'=>$ticketId]);$rows=[];foreach($statement->fetchAll()as$row)$rows[]=['id'=>$row['id'],'ticketId'=>$ticketId,'bidderOrganisationId'=>$row['bidder_organisation_id'],'bidderUserId'=>$row['bidder_user_id'],'bidderRole'=>$row['bidder_role'],'amount'=>(float)$row['amount'],'currency'=>$row['currency'],'scope'=>$row['scope'],'exclusions'=>$this->decode($row['exclusions']),'qualifications'=>$this->decode($row['qualifications']),'deliverables'=>$this->decode($row['deliverables']),'timeline'=>$row['timeline'],'conflictDeclared'=>(bool)$row['conflict_declared'],'conflictDetail'=>$row['conflict_detail'],'snapshotSha256'=>$row['snapshot_sha256'],'status'=>$row['status'],'submittedAt'=>$row['submitted_at']];return$rows;
