    /** @return array<string,mixed> */
    public function getTicket(string$organisationId,string$userId,string$role,string$ticketId):array
    {
        $this->assertMember($organisationId,$userId,$role,['owner','admin','member','viewer']);$row=$this->ticketRow($ticketId,false);if($row['organisation_id']!==$organisationId&&$row['holder_user_id']!==$userId&&!$this->policy->canViewTicket($row['invitation_type'],$this->invitees($ticketId),$userId))throw new JobTicketMarketplaceException('job_ticket_not_found');return$this->ticket($ticketId);
    }

    /** @return array<string,mixed> */
    private function ticket(string$id):array{$r=$this->ticketRow($id,false);return['id'=>$r['id'],'organisationId'=>$r['organisation_id'],'projectId'=>$r['project_id'],'parentTicketId'=>$r['parent_ticket_id'],'posterUserId'=>$r['poster_user_id'],'posterType'=>$r['poster_type'],'title'=>$r['title'],'description'=>$r['description'],'deliverables'=>$this->decode($r['deliverables']),'budget'=>['min'=>(float)$r['budget_min'],'max'=>(float)$r['budget_max'],'currency'=>$r['currency']],'deadline'=>$r['deadline'],'location'=>$r['location'],'phase'=>$r['phase'],'requiredRegistrations'=>$this->decode($r['required_registrations']),'invitationType'=>$r['invitation_type'],'classification'=>$this->decode($r['classification_snapshot']),'classificationSha256'=>$r['classification_sha256'],'platformFee'=>['percent'=>(float)$r['platform_fee_percent'],'disclosure'=>$r['platform_fee_disclosure'],'paymentExecutionClaimed'=>false],'automaticAward'=>(bool)$r['automatic_award'],'status'=>$r['status'],'holderOrganisationId'=>$r['holder_organisation_id'],'holderUserId'=>$r['holder_user_id'],'acceptedQuotationId'=>$r['accepted_quotation_id'],'version'=>(int)$r['version'],'createdAt'=>$r['created_at'],'updatedAt'=>$r['updated_at']];}
    /** @return array<string,mixed> */private function ticketRow(string$id,bool$lock):array{$s=$this->pdo->prepare('SELECT LOWER(HEX(id)) id,LOWER(HEX(organisation_id)) organisation_id,LOWER(HEX(project_id)) project_id,LOWER(HEX(parent_ticket_id)) parent_ticket_id,LOWER(HEX(poster_user_id)) poster_user_id,poster_type,title,description,deliverables,budget_min,budget_max,currency,DATE_FORMAT(deadline,\'%Y-%m-%d\') deadline,location,phase,required_registrations,invitation_type,platform_fee_percent,platform_fee_disclosure,classification_snapshot,classification_sha256,automatic_award,status,LOWER(HEX(holder_organisation_id)) holder_organisation_id,LOWER(HEX(holder_user_id)) holder_user_id,LOWER(HEX(accepted_quotation_id)) accepted_quotation_id,version,DATE_FORMAT(created_at,\'%Y-%m-%dT%H:%i:%s.%fZ\') created_at,DATE_FORMAT(updated_at,\'%Y-%m-%dT%H:%i:%s.%fZ\') updated_at FROM job_tickets WHERE id=UNHEX(:id)'.($lock?' FOR UPDATE':''));$s->execute(['id'=>$this->id($id,'job_ticket_not_found')]);$r=$s->fetch();if(!is_array($r))throw new JobTicketMarketplaceException('job_ticket_not_found');return$r;}
    /** @param array<string,bool> $visited @return array{ticket:array<string,mixed>,children:list<array<string,mixed>>} */private function treeNode(string$id,array&$visited,int$depth):array{if($depth>20||isset($visited[$id]))throw new JobTicketMarketplaceException('job_ticket_tree_integrity_failed');$visited[$id]=true;$s=$this->pdo->prepare('SELECT LOWER(HEX(child_ticket_id)) child_id,role_key FROM job_ticket_expansions WHERE parent_ticket_id=UNHEX(:id) ORDER BY created_at,id');$s->execute(['id'=>$id]);$children=[];foreach($s->fetchAll()as$row){$node=$this->treeNode($row['child_id'],$visited,$depth+1);$children[]=['role'=>$row['role_key'],...$node];}return['ticket'=>$this->ticket($id),'children'=>$children];}
    /** @return list<string> */private function invitees(string$ticketId):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(recipient_user_id)) FROM job_ticket_direct_invites WHERE ticket_id=UNHEX(:id) AND status<>'withdrawn'");$s->execute(['id'=>$ticketId]);return array_map('strval',$s->fetchAll(PDO::FETCH_COLUMN));}
    private function classificationRevision(string$o,string$ticket,int$revision,array$classification,string$reason,string$user,?string$replaces):void{$this->pdo->prepare('INSERT INTO job_ticket_classification_revisions(id,organisation_id,ticket_id,revision,classified_by,classification_snapshot,snapshot_sha256,replaces_sha256,reason,created_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:ticket),:revision,:classified,:snapshot,:sha,:replaces,:reason,UNHEX(:user))')->execute(['id'=>Identifier::generate(),'o'=>$o,'ticket'=>$ticket,'revision'=>$revision,'classified'=>$classification['classifiedBy'],'snapshot'=>$this->json($classification),'sha'=>$classification['sha256'],'replaces'=>$replaces,'reason'=>$reason,'user'=>$user]);}
    private function directInvite(string$o,?string$project,string$ticket,string$actor,string$recipient,string$title):void{$this->assertUser($recipient);$id=Identifier::generate();$this->pdo->prepare('INSERT INTO job_ticket_direct_invites(id,ticket_organisation_id,ticket_id,recipient_user_id,status,invited_by) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:ticket),UNHEX(:recipient),\'invited\',UNHEX(:actor))')->execute(['id'=>$id,'o'=>$o,'ticket'=>$ticket,'recipient'=>$recipient,'actor'=>$actor]);if($project!==null)$this->pdo->prepare('INSERT INTO inbox_items(id,organisation_id,project_id,assigned_user_id,event_type,title,detail,priority,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:project),UNHEX(:recipient),\'job_ticket_direct_invitation\',\'Direct job ticket invitation\',:detail,\'medium\',:payload)')->execute(['id'=>Identifier::generate(),'o'=>$o,'project'=>$project,'recipient'=>$recipient,'detail'=>$title.' is visible only to its direct invitees.','payload'=>$this->json(['ticketId'=>$ticket,'invitationId'=>$id])]);}
    /** @return list<array<string,mixed>> */private function matchProfiles(string$o,string$u):array{$s=$this->pdo->prepare("SELECT LOWER(HEX(created_by)) user_id,listing_type,disciplines_trades,service_areas,verification_status,capacity_status FROM marketplace_listings WHERE organisation_id=UNHEX(:o) AND created_by=UNHEX(:u) AND status='published'");$s->execute(['o'=>$o,'u'=>$u]);$profiles=[];foreach($s->fetchAll()as$row)$profiles[]=['userId'=>$row['user_id'],'role'=>in_array($row['listing_type'],['contractor','subcontractor'],true)?$row['listing_type']:'registered_bep','disciplines'=>$this->decode($row['disciplines_trades']),'serviceAreas'=>$this->decode($row['service_areas']),'verificationStatus'=>$row['verification_status'],'capacityStatus'=>$row['capacity_status']];return$profiles;}
    private function assertBidderEvidence(string$o,string$u,string$role):void{if($role==='registered_bep'){$s=$this->pdo->prepare("SELECT COUNT(*) FROM verification_records WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND kind='professional_registration' AND grade IN ('manually_reviewed','externally_verified') AND reviewed_by IS NOT NULL AND reviewed_by<>user_id AND (expires_on IS NULL OR expires_on>=UTC_DATE())");$s->execute(['o'=>$o,'u'=>$u]);if((int)$s->fetchColumn()!==1)throw new JobTicketMarketplaceException('job_ticket_registered_bep_verification_required');return;}if(str_starts_with($role,'freelancer_')){$s=$this->pdo->prepare("SELECT registration_status FROM freelancer_profiles WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='published' AND supervisor_required=1 AND independent_appointment_permitted=0");$s->execute(['o'=>$o,'u'=>$u]);$status=$s->fetchColumn();$expected=$role==='freelancer_candidate'?'candidate':'specialist';if($status!==$expected)throw new JobTicketMarketplaceException('job_ticket_freelancer_profile_required');return;}$type=$role==='contractor'?'contractor':'subcontractor';$s=$this->pdo->prepare("SELECT COUNT(*) FROM marketplace_listings WHERE organisation_id=UNHEX(:o) AND created_by=UNHEX(:u) AND listing_type=:type AND status='published' AND verification_status='verified'");$s->execute(['o'=>$o,'u'=>$u,'type'=>$type]);if((int)$s->fetchColumn()<1)throw new JobTicketMarketplaceException('job_ticket_bidder_verification_required');}
    /** @param array<string,mixed> $p @return array<string,mixed> */private function normaliseQuotation(array$p):array{$amount=$p['amount']??null;if((!is_int($amount)&&!is_float($amount))||!is_finite((float)$amount)||(float)$amount<=0)throw new JobTicketMarketplaceException('job_ticket_quotation_amount_invalid');$currency=$p['currency']??null;if(!is_string($currency)||!in_array($currency,['ZAR','USD','EUR','GBP'],true))throw new JobTicketMarketplaceException('job_ticket_quotation_currency_invalid');if(!is_bool($p['conflictDeclared']??null))throw new JobTicketMarketplaceException('job_ticket_quotation_conflict_invalid');$detail=$p['conflictDetail']??null;if($p['conflictDeclared']&&(!is_string($detail)||trim($detail)===''))throw new JobTicketMarketplaceException('job_ticket_quotation_conflict_detail_required');return['amount'=>round((float)$amount,2),'currency'=>$currency,'scope'=>$this->text($p['scope']??null,5000,'job_ticket_quotation_scope_required'),'exclusions'=>$this->strings($p['exclusions']??[],100,500,'job_ticket_quotation_exclusions_invalid'),'qualifications'=>$this->strings($p['qualifications']??[],100,500,'job_ticket_quotation_qualifications_invalid'),'deliverables'=>$this->strings($p['deliverables']??[],100,220,'job_ticket_quotation_deliverables_invalid'),'timeline'=>$this->text($p['timeline']??null,500,'job_ticket_quotation_timeline_required'),'conflictDeclared'=>$p['conflictDeclared'],'conflictDetail'=>$detail===null?null:$this->text($detail,1000,'job_ticket_quotation_conflict_detail_invalid')];}
    private function ticketInbox(array$ticket,string$recipient,string$type,string$title,string$detail,array$payload):void{if($ticket['project_id']===null)return;$this->pdo->prepare('INSERT INTO inbox_items(id,organisation_id,project_id,assigned_user_id,event_type,title,detail,priority,payload) VALUES(UNHEX(:id),UNHEX(:o),UNHEX(:project),UNHEX(:recipient),:type,:title,:detail,\'medium\',:payload)')->execute(['id'=>Identifier::generate(),'o'=>$ticket['organisation_id'],'project'=>$ticket['project_id'],'recipient'=>$recipient,'type'=>$type,'title'=>$title,'detail'=>$detail,'payload'=>$this->json($payload)]);}
    private function assertProject(string$o,string$id):void{$s=$this->pdo->prepare('SELECT COUNT(*) FROM projects WHERE id=UNHEX(:id) AND organisation_id=UNHEX(:o)');$s->execute(['id'=>$this->id($id,'job_ticket_project_not_found'),'o'=>$o]);if((int)$s->fetchColumn()!==1)throw new JobTicketMarketplaceException('job_ticket_project_not_found');}
    private function assertUser(string$id):void{$s=$this->pdo->prepare('SELECT COUNT(*) FROM users WHERE id=UNHEX(:id) AND status=\'active\'');$s->execute(['id'=>$this->id($id,'job_ticket_invitee_not_found')]);if((int)$s->fetchColumn()!==1)throw new JobTicketMarketplaceException('job_ticket_invitee_not_found');}
    /** @param list<string> $allowed */private function assertMember(string$o,string$u,string$claimed,array$allowed):void{$s=$this->pdo->prepare("SELECT role FROM organisation_memberships WHERE organisation_id=UNHEX(:o) AND user_id=UNHEX(:u) AND status='active'");$s->execute(['o'=>$this->id($o,'job_ticket_permission_denied'),'u'=>$this->id($u,'job_ticket_permission_denied')]);$actual=$s->fetchColumn();if(!is_string($actual)||!hash_equals($actual,$claimed)||!in_array($actual,$allowed,true))throw new JobTicketMarketplaceException('job_ticket_permission_denied');}
    private function id(string$id,string$error):string{if(preg_match('/\A[a-f0-9]{32}\z/',$id)!==1)throw new JobTicketMarketplaceException($error);return$id;}
    private function text(mixed$value,int$max,string$error):string{if(!is_string($value)||($value=trim($value))===''||mb_strlen($value)>$max)throw new JobTicketMarketplaceException($error);return$value;}
    private function slug(mixed$value,int$max,string$error):string{$value=$this->text($value,$max,$error);if(preg_match('/\A[a-z0-9][a-z0-9_-]*\z/',$value)!==1)throw new JobTicketMarketplaceException($error);return$value;}
    /** @return list<string> */private function strings(mixed$value,int$limit,int$max,string$error):array{if(!is_array($value)||count($value)>$limit)throw new JobTicketMarketplaceException($error);$out=[];foreach($value as$item){$item=$this->text($item,$max,$error);$out[$item]=true;}$out=array_keys($out);sort($out,SORT_STRING);return$out;}
    private function json(mixed$value):string{return json_encode($value,JSON_THROW_ON_ERROR|JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE|JSON_PRESERVE_ZERO_FRACTION);}
    /** @return array<string,mixed> */private function decode(string$value):array{$decoded=json_decode($value,true,flags:JSON_THROW_ON_ERROR);if(!is_array($decoded))throw new JobTicketMarketplaceException('job_ticket_integrity_failed');return$decoded;}
    private function transaction(callable$operation):mixed{$this->pdo->beginTransaction();try{$result=$operation();$this->pdo->commit();return$result;}catch(Throwable$e){if($this->pdo->inTransaction())$this->pdo->rollBack();throw$e;}}
}
